{
  "name": "在线测量显示组件",
  "name_en": "Online Measurement Display",
  "manufacturer": "Zahner",
  "description": "这是一种非物理的软件显示组件，用于在实验进行过程中实时显示测量数据。它从测量设备的数据接收对象获取数据，并将时间、电压、电流等轨迹发送到独立的绘图进程中进行在线可视化，常用于电化学/恒电位仪测量过程的实时曲线监看。",
  "description_en": "This is a non-physical software display component for showing measurement data live during an experiment. It receives data from a measurement device's data receiver and forwards time, voltage, current, and related traces to a separate plotting process for online visualization, typically for real-time monitoring of electrochemical/potentiostat measurements.",
  "actions": [
    {
      "action_name": "auto-stopProcessingLoop",
      "description": "停止在线数据处理循环。",
      "description_en": "Stop the online data processing loop."
    },
    {
      "action_name": "auto-setMinimumSendInterval",
      "description": "设置发送到在线显示的数据最小时间间隔。",
      "description_en": "Set the minimum time interval for sending data to the online display."
    },
    {
      "action_name": "auto-processingLoop",
      "description": "处理接收的测量数据并将其发送到绘图进程进行实时显示。",
      "description_en": "Process incoming measurement data and send it to the plotting process for live display."
    },
    {
      "action_name": "auto-close",
      "description": "关闭在线显示。",
      "description_en": "Close the online display."
    }
  ],
  "tag_hints": [
    "live plotting",
    "measurement visualization",
    "electrochemistry data display",
    "potentiostat",
    "real-time monitoring",
    "Matplotlib display process"
  ]
}

